///
/// Returns
/// * The contents of the file referenced by the specified ID
pub async fn get_file(
    ctx: &dyn RequestContext,
    id: crate::types::id::ObjectId,
) -> Result<Vec<u8>, Error> {
    let path = "/v1/api/ulv2/drive/file/:id".replace(":id", &id.to_string());
    let res = ctx.get(&path, None, None).await?;
    Ok(res)
}

/// Uploads a chunk of a file by file id and chunk index.
///
/// # Arguments
///
/// * `ctx` - A request context object
/// * `file_id` - The ID of the file to which to set a file chunk
/// * `idx` - The index of the file chunk to set
/// * `hash` - The hash of the chunk to upload.
/// * `chunk` - Binary file chunk data
pub async fn put_file_chunk(
    ctx: &dyn RequestContext,
    file_id: crate::types::id::ObjectId,
    idx: i64,
    hash: &str,
    chunk: Vec<u8>,
) -> Result<(), Error> {
    let path = "/v1/api/ulv2/drive/file/:file_id/:idx"
        .replace(":file_id", &file_id.to_string())
        .replace(":idx", &idx.to_string());
    let mut params = ParamMap::new();
    params.insert("hash".to_owned(), hash.to_owned());

    let body = Bytes::from(chunk);
    ctx.put(&path, body, "application/octet-stream", Some(params), None)
        .await?;
    Ok(())
}

